 Check(TEXT("construction.only_locked_elephant_tier_builds_high_placed_lower_age_site"),Farm->Progress>Progress&&Curelom->Order==TEXT("idle")&&!W->CanBuildSite(*Curelom,*Farm)&&!W->CanBuildSite(*Cumelom,*Farm)&&W->CanBuildSite(*Elephant,*Farm));
