 Reset();HQ=Spawn(TEXT("seat_of_the_people"),{20,20});Worker=Spawn(TEXT("industrious_laborer"),{25,20});const bool SiteWasVisible=W->VisiblePoint(0,{120,120});W->Build(*Worker,TEXT("fields_of_grain"),{120,120},C);Farm=nullptr;for(auto& KV:W->Entities)if(W->D(*KV.Value).Id==TEXT("fields_of_grain"))Farm=KV.Value.Get();Check(TEXT("construction.explored_fog_accepts_foundation"),Farm&&!SiteWasVisible);
