 Reset(TEXT("gadianton"));HQ=Spawn(TEXT("seat_of_the_people"),{20,20});Spawn(TEXT("seat_of_the_people"),{110,20},1);Store=Spawn(TEXT("storehouse_of_provisions"),{27,20});auto Victim=Spawn(TEXT("storehouse_of_provisions"),{42,20},1);auto Raider=Spawn(TEXT("gadianton_robber"),Victim->Pos-FVector2D(W->D(*Victim).Radius+1,0));W->Players[0].Favor=40;W->Players[0].Upgrades.Add(TEXT("plunder_share"));float Mult=W->PlunderMultiplier(0);FVector VictimBefore=W->Players[1].Resources;Raider->Order=TEXT("raid");Raider->Target=Raider->RaidSource=Victim->Id;Raider->Channel=3;W->Economy(*Raider,1);FVector Taken=VictimBefore-W->Players[1].Resources;
