 W->Players[1].Resources=FVector(100,100,0);Raider->Cargo=FVector::ZeroVector;W->Economy(*Raider,1);Check(TEXT("raid.empty_stock_share_is_redistributed_evenly"),W->Players[1].Resources.Equals(FVector(98.5,98.5,0),.001f)&&Raider->Cargo.Equals(FVector(3,3,0),.001f));
