 Reset(TEXT("gadianton"));Store=Spawn(TEXT("storehouse_of_provisions"),{40,40},1);Worker=Spawn(TEXT("industrious_laborer"),{43,40},1);auto Camper=Spawn(TEXT("gadianton_robber"),{44,40});W->Time=10;Camper->LastMove=-100;Camper->RevealedUntil=0;W->Players[0].Favor=80;W->Players[0].Upgrades.Add(TEXT("compromised_storehouses"));FVector OwnerBefore=W->Players[1].Resources,ThiefBefore=W->Players[0].Resources;W->DepositResources(*Worker,*Store,FVector(10,20,30));Check(TEXT("diversion.stealth_camper_splits_deposit_without_duplicate_credit"),W->Players[1].Resources.Equals(OwnerBefore+FVector(5,10,15),.001f)&&W->Players[0].Resources.Equals(ThiefBefore+FVector(5,10,15),.001f));
 W->Players[0].Favor=100;OwnerBefore=W->Players[1].Resources;ThiefBefore=W->Players[0].Resources;W->DepositResources(*Worker,*Store,FVector(4,6,8));Check(TEXT("diversion.full_stat_redirects_entire_deposit"),W->Players[1].Resources==OwnerBefore&&W->Players[0].Resources.Equals(ThiefBefore+FVector(4,6,8),.001f));
 W->Players[0].Favor=70;OwnerBefore=W->Players[1].Resources;W->DepositResources(*Worker,*Store,FVector(3));Check(TEXT("diversion.requires_stat_strictly_above_seventy"),W->Players[1].Resources.Equals(OwnerBefore+FVector(3),.001f));

